// Parsear respuesta del AI Agent
let response = '';

// El AI Agent devuelve en .output
if ($input.item.json.output) {
  response = $input.item.json.output;
}
else if ($input.item.json.message?.content) {
  response = $input.item.json.message.content;
}
else if ($input.item.json.text) {
  response = $input.item.json.text;
}
else if (typeof $input.item.json === 'string') {
  response = $input.item.json;
}

if (!response) {
  console.log('INPUT:', JSON.stringify($input.item.json, null, 2));
  throw new Error('No se obtuvo respuesta del AI Agent');
}

// Limpiar saltos de línea escapados
response = response.replace(/\\n/g, ' ').trim();

// Extraer el objeto JSON (tomamos el primer bloque { ... })
let jsonMatch = response.match(/\{[\s\S]*\}/);
if (!jsonMatch) {
  console.log('Respuesta:', response);
  throw new Error('No se encontró JSON');
}

let jsonString = jsonMatch[0];

// Intento suave de arreglar claves sin comillas en el primer nivel
jsonString = jsonString.replace(
  /^(\s*)(\w+)\s*:/gm,
  '$1"$2":'
);

try {
  const parsed = JSON.parse(jsonString);

  // Validaciones mínimas
  if (!parsed.intent || !parsed.reply) {
    throw new Error('Faltan campos requeridos (intent/reply)');
  }

  // Normalizaciones
  const intent = String(parsed.intent).toUpperCase(); // FAQ / BOT_BUILD
  if (intent !== 'FAQ' && intent !== 'BOT_BUILD') {
    // no lo cortamos, pero lo dejamos trazado
    console.log('Intent inesperado:', parsed.intent);
  }

  const estadoRaw = (parsed.estado ?? 'bot').toString().toLowerCase();
  const estado = (estadoRaw === 'humano') ? 'humano' : 'bot';

  const briefingStatusRaw = (parsed.briefing_status ?? 'incompleto').toString().toLowerCase();
  const briefing_status = (briefingStatusRaw === 'completo') ? 'completo' : 'incompleto';

  const mode_change = parsed.mode_change === true;

  const is_finished = parsed.is_finished === true;
  const needs_human = parsed.needs_human === true;

  const updates = (parsed.updates && typeof parsed.updates === 'object') ? parsed.updates : {};

  const reply = String(parsed.reply);

  return {
    intent,
    mode_change,
    updates,
    reply,
    is_finished,
    needs_human,
    estado,
    briefing_status
  };

} catch (e) {
  console.log("NO SE PUDO PARSEAR JSON:");
  console.log(jsonString);
  throw new Error('No se pudo parsear: ' + e.message);
}

// =======================================
// 10. PREPARAR UPDATE DB1 (PRO) - PARA TU SHEET + form_data + pending_fields
// =======================================

function safeGet(obj, path, fallback) {
  try {
    return path.reduce((acc, k) => (acc && acc[k] !== undefined ? acc[k] : undefined), obj) ?? fallback;
  } catch {
    return fallback;
  }
}

function asArray(v) {
  return Array.isArray(v) ? v : (v ? [v] : []);
}

function parseJsonMaybe(v, fallback) {
  if (typeof v !== "string") return (v ?? fallback);
  try { return JSON.parse(v); } catch { return fallback; }
}

function nowIso() {
  return new Date().toISOString();
}

// --- Inputs ---
const currentContext = $('Consolidar BDD').first().json || {};
const llm = $('9. Parse JSON LLM1')?.first()?.json || $input.item.json || {};

// --- Sheet fields base ---
const userId = currentContext.user_id || currentContext.phone || null;
const phone = currentContext.phone || null;
const sessionId = currentContext.session_id || null;
const source = currentContext.source || 'web';

// --- Prev state ---
const prevMode = safeGet(currentContext, ['current_mode'], safeGet(currentContext, ['mode'], 'FAQ'));
const prevEstado = safeGet(currentContext, ['estado'], 'bot');

// --- Mode switch ---
const modeChange = !!llm.mode_change;
const newMode = modeChange ? (llm.intent || prevMode) : prevMode;

// --- Human ---
const needsHuman = !!llm.needs_human;
const newEstado = needsHuman ? 'humano' : prevEstado;

// --- Form schema ---
const formSchema = asArray(currentContext.form_schema || []);

// --- form_data from sheet (string -> obj) ---
let prevFormData = currentContext.form_data ?? {};
prevFormData = parseJsonMaybe(prevFormData, {});
if (typeof prevFormData !== "object" || Array.isArray(prevFormData) || prevFormData === null) prevFormData = {};

// --- updates from LLM ---
const updates = (llm.updates && typeof llm.updates === 'object') ? llm.updates : {};
const mergedFormData = { ...prevFormData, ...updates };

// --- pending_fields ---
function computePending(schema, data) {
  if (!schema.length) return [];
  return schema
    .filter(f => f && f.key)
    .filter(f => f.required === true)
    .map(f => f.key)
    .filter(k => {
      const v = data[k];
      return v === undefined || v === null || (typeof v === 'string' && v.trim() === '');
    });
}
const pendingFields = computePending(formSchema, mergedFormData);

// --- History from sheet (string -> array) ---
let history = currentContext.conversation_history ?? [];
history = parseJsonMaybe(history, history);
history = asArray(history);

// append last turn
const userMsg = currentContext.current_message || currentContext.message || '';
const assistantReply = llm.reply || '';

if (userMsg) history.push({ role: 'user', content: userMsg, timestamp: nowIso() });
if (assistantReply) history.push({ role: 'assistant', content: assistantReply, timestamp: nowIso() });

// --- created_at / last_updated ---
const createdAt = currentContext.created_at || nowIso();
const lastUpdated = nowIso();

// --- is_finished ---
const isFinished = (newMode === 'BOT_BUILD' && pendingFields.length === 0) ? true : !!llm.is_finished;

// --- Nombre / Email (si el LLM los completa como updates y querés guardarlos)
// Si en tu schema usás "nombre" y "email", quedan en form_data igual.
// Además, si querés guardarlos “planos”:
const nombre = currentContext.nombre || '';
const email = currentContext.email || '';

// --- Strings para Sheets ---
const historyStr = JSON.stringify(history);
const formDataStr = JSON.stringify(mergedFormData);
const pendingStr = JSON.stringify(pendingFields);

// --- Extract individual briefing fields ---
const negocio = mergedFormData.negocio || '';
const rubro = mergedFormData.rubro || '';
const objetivo_bot = mergedFormData.objetivo_bot || '';
const canal = mergedFormData.canal || '';
const integraciones = mergedFormData.integraciones || '';
const faq_only = mergedFormData.faq_only || '';
const plazo = mergedFormData.plazo || '';
const presupuesto_estimado = mergedFormData.presupuesto_estimado || '';
const reunion_preferencia = mergedFormData.reunion_preferencia || '';
const briefing_status = llm.briefing_status || 'incompleto';

// --- Payload final EXACTO para tu Sheet ---
const dbUpdate = {
  user_id: userId,
  session_id: sessionId,
  phone: phone,
  source: source,

  estado: newEstado,
  mode: newMode,
  needs_human: needsHuman,

  nombre: nombre,
  email: email,

  is_finished: isFinished,
  created_at: createdAt,
  last_updated: lastUpdated,

  // persistencia pro
  conversation_history: historyStr,
  form_data: formDataStr,
  pending_fields: pendingStr,

  // individual briefing fields
  negocio: negocio,
  rubro: rubro,
  objetivo_bot: objetivo_bot,
  canal: canal,
  integraciones: integraciones,
  faq_only: faq_only,
  plazo: plazo,
  presupuesto_estimado: presupuesto_estimado,
  reunion_preferencia: reunion_preferencia,
  briefing_status: briefing_status,

  // para responder al webhook
  reply: assistantReply
};

return { json: dbUpdate };

const userData = $input.item.json;

// Parsear conversation_history
let conversationHistory = [];
if (userData.conversation_history) {
  let historyStr = String(userData.conversation_history).trim();
  // Remover apóstrofes de Google Sheets (todos, no solo el primero)
  historyStr = historyStr.replace(/^'+|'+$/g, '');

  if (historyStr && historyStr !== 'null' && historyStr !== '[]') {
    try {
      conversationHistory = JSON.parse(historyStr);
      if (!Array.isArray(conversationHistory)) {
        conversationHistory = [];
      }
    } catch(e) {
      console.log("Error parseando conversation_history:", e.message);
      conversationHistory = [];
    }
  }
}

// Detectar usuario nuevo basándose en historial VACÍO
// Esto es más robusto que basarse en 'mode'
const isNewUser = conversationHistory.length === 0;

return {
  ...userData,
  is_new_user: isNewUser,
  conversation_history: conversationHistory,
  current_message: $('Validar Datos').first().json.message
};

const userData = $input.item.json;

return {
  ...userData,
  form_schema: [
    { key: "negocio", question: "Perfecto. ¿Cómo se llama tu negocio?", required: true },
    { key: "rubro", question: "¿En qué rubro estás? (ej: ferretería, fitness, e-commerce, servicios, educación)", required: true },
    { key: "objetivo_bot", question: "¿Para qué querés el bot principalmente? (FAQ / ventas / soporte / turnos / mixto)", required: true },
    { key: "canal", question: "¿Dónde querés usar el bot? (Web / WhatsApp / Instagram / Multi)", required: true },
    { key: "integraciones", question: "¿Tiene que conectarse a algo? (Google Sheets / CRM / pagos / turnos / otro). Si no, poné “no”.", required: true },
    { key: "faq_only", question: "¿Lo querés solo para responder preguntas frecuentes? (sí/no)", required: true },
    { key: "plazo", question: "¿Para cuándo te gustaría tenerlo funcionando?", required: true },
    { key: "presupuesto_estimado", question: "¿Tenés un rango de presupuesto estimado? (opcional: podés poner “no sé”)", required: false },
    { key: "reunion_preferencia", question: "¿Querés agendar una reunión para ver el proyecto? (sí/no)", required: true }
  ]
};

