// $input.all() trae todas las filas de la BDD
const rows = $input.all().map(i => i.json);

// Armá un texto “knowledge base” con columnas relevantes
// (ajustá keys según tu sheet: pregunta/respuesta/categoria, etc)
const kb = rows.map(r => {
  const q = r.pregunta || r.question || r.q || '';
  const a = r.respuesta || r.answer || r.a || '';
  const c = r.categoria || r.category || '';
  return `Categoria: ${c}\nQ: ${q}\nA: ${a}`.trim();
}).filter(Boolean).join('\n\n---\n\n');

// Recupero el item del usuario desde Procesar/Schema
// (como Base generó múltiples items, acá lo que importa es devolver 1 SOLO item “final”)
const user = $('Procesar').first().json;

// devolvemos 1 item único
return [{
  json: {
    ...user,
    form_schema: $('Schema').first().json.form_schema,
    bdd_text: kb
  },
  pairedItem: { item: 0 }   // 👈 mantiene el pairing (usa el primer item como referencia)
}];

// ============================================
// VALIDAR DATOS - Pre-procesamiento para Sheets
// ============================================

const normalizerData = $input.first().json;

console.log('📥 Payload recibido de Input Adapter:', JSON.stringify(normalizerData, null, 2));

// Validar que phone existe
if (!normalizerData.phone) {
  const error = `❌ ERROR: Campo 'phone' no encontrado en el nodo Input Adapter.

Payload recibido:
${JSON.stringify(normalizerData, null, 2)}`;

  throw new Error(error);
}

const cleanPhone = normalizerData.phone.toString().trim();

// Validar formato básico
if (cleanPhone.length < 8) {
  throw new Error('❌ ERROR: Phone number demasiado corto: ' + cleanPhone);
}

// Generar user_id único
const userId = 'U-' + cleanPhone;

// Timestamps
const now = new Date().toISOString();

// Construir output estandarizado
const output = {
  phone: cleanPhone,
  user_id: userId,
  session_id: cleanPhone,
  source: 'web',
  created_at: now,
  last_updated: now,
  message: normalizerData.message || ''
};

console.log('✅ Datos validados:', JSON.stringify(output, null, 2));

return { json: output };
